using Ohno.CircleGame.Gameplay;
namespace Ohno.QA13;
public static partial class Tests
{
    static void Completion()
    {
        foreach(int t in new[]{1199,1200,1201})Add("C/strict-B200-"+t,"E027 M2276 strict comparison",()=>{using var f=Flow();f.Observe(t);Eq(f.Stage,t>1200?RankStage.FinalizationEligible:RankStage.Active);Eq(f.Finalized,false);Eq(f.Transitions.Pending,null);});
        foreach(int t in new[]{-1,0,1,999})Add("C/q0-positive-"+t,"M2276 positive T and separate q0",()=>{using var f=Flow();f.Observe(t,clockState:0);Eq(f.Stage,t>0?RankStage.FinalizationEligible:RankStage.Active);});
        Add("C/nonzero-q-no-shortcut","M2276 q branch",()=>{using var f=Flow();f.Observe(999,clockState:2);Eq(f.Stage,RankStage.Active);});
        foreach(string gate in new[]{"continuation","suspension","failure","unknown-failure"})Add("C/gate-"+gate,"E027 caller failure and M2276 gates",()=>{using var f=Flow(failed:()=>gate=="failure"?true:gate=="unknown-failure"?null:false);f.Observe(10000,continuation:gate=="continuation",suspended:gate=="suspension");Eq(f.Stage,RankStage.Active);Eq(f.Complete(),false);Eq(f.Finalized,false);});
        Add("C/pending-accounting","E027 no synthetic drain; R15 ENGINEERING safety",()=>{bool pending=true;using var f=Flow(pending:()=>pending);f.Observe(1201);Eq(f.Complete(),false);Eq(f.Finalized,false);Eq(f.HandlerRecord.Success,false);pending=false;Eq(f.Complete(),true);Eq(f.Finalized,true);});
        Add("C/count-mismatch-still-finalized","E027 M0aa5/M2b5a then M0acd",()=>{using var f=Flow(new Record{C300=9});Finish(f);Eq(f.HandlerRecord.Valid,false);Eq(f.HandlerRecord.Success,true);Eq(f.Finalized,true);Eq(f.HandlerRecord.N300,(ushort)9);});
        Add("C/latch-prevents-repeat","E027 F1397 first store",()=>{var r=new Record();using var f=Flow(r);Finish(f);r.Success=false;f.Observe(1202);Eq(f.Complete(),false);Eq(r.Success,false);Eq(f.Finalized,true);});
        foreach(int t in new[]{3999,4000,4001})Add("C/B3000-"+t,"E027 inclusive departure boundary",()=>{using var f=Flow();Finish(f);f.Observe(t);Eq(f.Stage,t<4000?RankStage.RecordCompleted:RankStage.RankAdmitted);Eq(f.Transitions.Current,RankMode.Play);});
        foreach(int t in new[]{4499,4500,4501})Add("C/event-horizon-"+t,"E027 nonempty J and Z-500 inclusive",()=>{using var f=Flow();Finish(f);f.Observe(t,timedEventCount:1,eventHorizon:5000);Eq(f.Stage,t<4500?RankStage.RecordCompleted:RankStage.RankAdmitted);});
        Add("C/empty-event-horizon-engineering","E027 count0 bypass; host supplies empty projection",()=>{using var f=Flow();Finish(f);f.Observe(4000,timedEventCount:0,eventHorizon:int.MaxValue);Eq(f.Stage,RankStage.RankAdmitted);});
        Add("C/same-observation-not-completion","E027 finalization distinct from request",()=>{using var f=Flow();f.Observe(4001);Eq(f.Stage,RankStage.FinalizationEligible);Eq(f.Transitions.Pending,null);f.Complete();f.Observe(4001);Eq(f.Stage,RankStage.RankAdmitted);});
        Add("C/reversed-time-no-fabrication","Artificial times; engineering model only",()=>{using var f=Flow();f.Observe(1199);f.Observe(-999);Eq(f.Finalized,false);Eq(f.HandlerRecord.N300,(ushort)10);});
        Add("C/unchecked-end-overflow","E027 signed unchecked B+200",()=>{using var f=new RankSession(new Record(),int.MaxValue-10,10,()=>false);f.Observe(1);Eq(f.Stage,RankStage.FinalizationEligible);});
        Add("C/maximum-end-not-last-start","E027 B maximum; E042 finite Rank constructor",()=>{var m=Map("256,192,1000,8,0,6000,0:0:0:0:\n256,192,5000,1,0,0:0:0:0:");var s=CircleSession.CreateFreshOrdinary(m,ScoreConfiguration.FromBeatmap(m));using var f=new RankSession(s);Eq(f.MaximumEnd,6000);Eq(m.Circles[0].StartTime,5000);});
        Add("C/unsupported-completion-explicit","ENGINEERING unavailable result without failure provenance",()=>{using var f=Flow();f.UnsupportedCompletion();Eq(f.Stage,RankStage.Unavailable);Eq(f.Finalized,false);Eq(f.RequestRank(),TransitionDecision.Rejected);});
    }
    static void Transitions()
    {
        Add("T/not-finalized-rejection","E027 latch separate from Rank admission",()=>{using var f=Flow();Eq(f.RequestRank(),TransitionDecision.Rejected);Eq(f.Transitions.Pending,null);Eq(f.Transitions.Current,RankMode.Play);});
        Add("T/deferred-resubmit","E003 M46ad/M46e6 live guards; bounded R15 policy",()=>{using var f=Flow();Finish(f);f.Transitions.GateOpen=false;Eq(f.RequestRank(),TransitionDecision.Deferred);Eq(f.Stage,RankStage.RankRequested);Eq(f.Transitions.Pending,null);Eq(f.Commit(()=>throw new Exception("unreached")),false);f.Transitions.GateOpen=true;Eq(f.RequestRank(),TransitionDecision.Accepted);Eq(f.Stage,RankStage.RankAdmitted);Eq(f.Transitions.Current,RankMode.Play);});
        Add("T/rejected-resubmit","E003 guard admission separate",()=>{using var f=Flow();Finish(f);f.Transitions.Allow=false;Eq(f.RequestRank(),TransitionDecision.Rejected);Eq(f.Stage,RankStage.RankRequested);Eq(f.Transitions.Phase,2);f.Transitions.Allow=true;Eq(f.RequestRank(),TransitionDecision.Accepted);Eq(f.Transitions.Phase,0);});
        Add("T/duplicate","E003 accepted pending duplicate",()=>{using var f=Flow();Finish(f);Eq(f.RequestRank(),TransitionDecision.Accepted);Eq(f.RequestRank(),TransitionDecision.Duplicate);Eq(f.Transitions.Pending,RankMode.Rank);});
        Add("T/commit-before-cleanup","M46b0:0072 current before disposal",()=>{using var f=Flow();Finish(f);f.RequestRank();Eq(f.Present(),false);Eq(f.Initialize(0),false);f.Commit(()=>{Eq(f.Transitions.Current,RankMode.Rank);Eq(f.Stage,RankStage.TransitionCommitted);Eq(f.SelectedRecord,null);Eq(f.Presentation,null);});Eq(f.Transitions.Pending,RankMode.Rank);});
        Add("T/initialize-then-present","M46b0 register/virtual initialize then matching pending clear",()=>{using var f=Flow();Finish(f);f.RequestRank();f.Commit(()=>{});Eq(f.Present(),false);Eq(f.Initialize(70),true);Eq(f.Stage,RankStage.ResultsInitialized);Eq(f.Transitions.Pending,null);Eq(f.Transitions.Phase,1);Eq(f.Present(),true);Eq(f.Present(),false);});
        Add("T/cleanup-throw-partial","E042 exceptions preserve preceding current-mode mutation",()=>{using var f=Flow();Finish(f);f.RequestRank();Throws<IOException>(()=>f.Commit(()=>throw new IOException("QA13 cleanup control")));Eq(f.Transitions.Current,RankMode.Rank);Eq(f.Stage,RankStage.TransitionCommitted);Eq(f.Transitions.Pending,RankMode.Rank);Eq(f.SelectedRecord,null);});
        Add("T/new-pending-survives","M46b0:0573 matching-current clear",()=>{using var f=Flow();Finish(f);f.RequestRank();f.Commit(()=>f.Transitions.Request(RankMode.SelectPlay));f.Initialize(0);Eq(f.Transitions.Pending,RankMode.SelectPlay);Eq(f.Transitions.Current,RankMode.Rank);});
        Add("T/initialized-idempotent-rejection","E042 reentrant initialization unsupported; R15 safety",()=>{using var f=Flow();Enter(f);var p=f.Presentation;Eq(f.Initialize(50),false);Yes(ReferenceEquals(p,f.Presentation),"no second capture");});
        foreach(double operand in new[]{9999d,10000d,10001d,double.NaN})Add("T/retry-threshold-"+operand.ToString(System.Globalization.CultureInfo.InvariantCulture),"E003 conditional ordered F2c51<10000",()=>{using var f=Flow();Enter(f);f.Transitions.RestrictRankRetry=true;f.Transitions.RetryOperand=operand;Eq(f.Retry(100),operand<10000?TransitionDecision.Rejected:TransitionDecision.Accepted);Eq(f.Transitions.Pending,operand<10000?null:RankMode.Play);});
        Add("T/back-fresh-destination","E042 M32e8 SelectPlay5; engineering destination",()=>{using var f=Flow();Enter(f);Eq(f.Back(),TransitionDecision.Accepted);Eq(f.Transitions.Pending,RankMode.SelectPlay);Eq(f.Back(),TransitionDecision.Duplicate);f.Commit(()=>{});Eq(f.Stage,RankStage.ChartSelection);Eq(f.GlobalRecord,null);});
        foreach(bool skipped in new[]{false,true})Add("T/retry-independent-skip-"+skipped,"E042 M32e1 discards M32e7 Boolean",()=>{using var f=Flow();Enter(f);if(skipped)f.Skip(1300);Eq(f.Retry(1300),TransitionDecision.Accepted);Eq(f.Transitions.Pending,RankMode.Play);Eq(f.Retry(1300),TransitionDecision.Duplicate);});
        Add("T/disposal-guards","ENGINEERING result lifetime no original-native disposal claim",()=>{using var f=Flow();Enter(f);var retained=f.SelectedRecord;f.Dispose();f.Dispose();Eq(f.Stage,RankStage.Disposed);Eq(f.GlobalRecord,null);Eq(f.Reveal,null);Yes(ReferenceEquals(f.SelectedRecord,retained),"retained alias distinguished");Eq(f.Retry(1),TransitionDecision.Rejected);Eq(f.Back(),TransitionDecision.Rejected);});
        Add("T/competing-pending-direct-model","ENGINEERING supported mode subset, Exit unavailable",()=>{var t=new RankTransitions();Eq(t.Request(RankMode.SelectPlay),TransitionDecision.Accepted);Eq(t.Request(RankMode.Rank),TransitionDecision.Accepted);Eq(t.Pending,RankMode.Rank);Eq(t.Request((RankMode)3),TransitionDecision.Rejected);Eq(t.Pending,RankMode.Rank);});
    }
}
